// A minimal TCP echo server: listen, accept, one goroutine per connection
package main

import ("bufio"; "log"; "net")

func main() {
    ln, err := net.Listen("tcp", ":9000")
    if err != nil { log.Fatal(err) }
    for {
        conn, err := ln.Accept() // each client gets its own socket (5-tuple)
        if err != nil { continue }
        go func(c net.Conn) {
            defer c.Close()
            sc := bufio.NewScanner(c)
            for sc.Scan() { c.Write([]byte(sc.Text() + "\n")) } // echo back
        }(conn)
    }
}

# Framing messages over a TCP stream with a 4-byte length prefix (TCP has no message boundaries)
import socket, struct

def send_msg(sock: socket.socket, payload: bytes):
    sock.sendall(struct.pack("!I", len(payload)) + payload)    # network byte order length, then data

def recv_exact(sock: socket.socket, n: int) -> bytes:
    buf = bytearray()
    while len(buf) < n:
        chunk = sock.recv(n - len(buf))                        # recv may return fewer bytes than asked
        if not chunk:
            raise ConnectionError("peer closed")
        buf += chunk
    return bytes(buf)

def recv_msg(sock: socket.socket) -> bytes:
    (length,) = struct.unpack("!I", recv_exact(sock, 4))
    if length > 10_000_000:
        raise ValueError("message too large")                  # never trust a length from the network
    return recv_exact(sock, length)

# Turn off Nagle for latency-sensitive request/response protocols
s = socket.create_connection(("example.com", 80), timeout=5)
s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)

// Node: a length-prefixed framing parser for a TCP stream (messages can be split or merged)
import net from "node:net";

net.createServer((socket) => {
  let buf = Buffer.alloc(0);
  socket.on("data", (chunk) => {
    buf = Buffer.concat([buf, chunk]);
    while (buf.length >= 4) {
      const len = buf.readUInt32BE(0);
      if (len > 10_000_000) return socket.destroy();            // protect against hostile lengths
      if (buf.length < 4 + len) break;                          // wait for the rest of the message
      const msg = buf.subarray(4, 4 + len);
      buf = buf.subarray(4 + len);
      socket.write(msg);                                        // echo
    }
  });
  socket.setNoDelay(true);
}).listen(9000);

// Node: inspect a server's certificate and DNS records
import dns from "node:dns/promises";
import tls from "node:tls";

console.log(await dns.resolve4("example.com"));          // A records
console.log(await dns.resolveMx("gmail.com"));            // MX records, with priorities

const socket = tls.connect(443, "example.com", { servername: "example.com" }, () => {
  const cert = socket.getPeerCertificate();
  console.log(socket.getProtocol(), socket.authorized, cert.subject.CN, "expires", cert.valid_to);
  socket.end();
});
